findings.codeql_raw_query:
/**
 * @name Dangerous function calls with untrusted input
 * @description Checking for potentially dangerous function calls that could be exploited
 * @kind path-problem
 * @problem.severity warning
 * @id py/dangerous-calls
 * @tags security
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module DangerousCallsConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Check for various dangerous operations
    exists(DataFlow::CallCfgNode call |
      // File operations
      call = API::moduleImport("os").getMember(["system", "popen", "popen2", "popen3", "popen4"]).getACall() and
      sink = call.getArg(0)
    ) or
    exists(DataFlow::CallCfgNode call |
      // Subprocess operations
      call = API::moduleImport("subprocess").getMember(["call", "check_call", "check_output", "Popen"]).getACall() and
      sink = call.getArg(0)
    ) or
    exists(DataFlow::CallCfgNode call |
      // Eval/exec
      call = API::builtin(["eval", "exec", "compile"]).getACall() and
      sink = call.getArg(0)
    ) or
    exists(DataFlow::CallCfgNode call |
      // Pickle operations
      call = API::moduleImport("pickle").getMember(["load", "loads"]).getACall() and
      sink = call.getArg(0)
    ) or
    exists(DataFlow::CallCfgNode call |
      // Marshal operations
      call = API::moduleImport("marshal").getMember(["load", "loads"]).getACall() and
      sink = call.getArg(0)
    ) or
    exists(DataFlow::CallCfgNode call |
      // YAML operations
      call = API::moduleImport("yaml").getMember(["load", "unsafe_load"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module DangerousCallsFlow = TaintTracking::Global<DangerousCallsConfig>;
import DangerousCallsFlow::PathGraph

from DangerousCallsFlow::PathNode source, DangerousCallsFlow::PathNode sink
where DangerousCallsFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potentially dangerous operation with untrusted input from $@.", source.getNode(), "user input"
